sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
	var emailAddr = new GlideAjax("GetEmailAddress");
	emailAddr.addParam("sysparm_name", "getEmail");
	emailAddr.addParam("sysparm_userID", g_form.getValue("u_requested_for"));

	emailAddr.getXML(populateField);

	function populateField (response){
		var emailAdd = response.responseXML.documentElement.getAttribute("answer");
		g_form.clearValue("u_requested_for_email");
		g_form.setValue("u_requested_for_email", emailAdd);
	}

   //Type appropriate comment here, and begin script below

}
